  if (err) {
    logger.error({ err }, "Error listening on port");
    process.exit(1);
  }
  logger.info({ port }, "Server listening");

  runMigrations().catch((err) => {
    logger.error({ err }, "Migration failed");
    process.exit(1);
  });
});

