108	
109	  const activeShows = shows.filter((s) => (s.dismantleDate ?? s.moveInDate) >= todayStr);
110	  const archivedShows = shows.filter((s) => (s.dismantleDate ?? s.moveInDate) < todayStr);
111	
112	  let totalOverdue = 0;
113	  for (const task of allTasks) {
114	    if (!task.completed && task.dueDate && task.dueDate < todayStr) {
115	      totalOverdue++;
116	    }
117	  }
118	  for (const eblast of allEblasts) {
119	    if (!eblast.sent && eblast.dueDate && eblast.dueDate < todayStr) {
120	      totalOverdue++;
121	    }
