  // Fix preset task name mismatch: seed used 'Check In / Submit' but key-task
  // detection in shows/dashboard routes expects 'Submit To FM/EC'
  await db.execute(sql`
    UPDATE preset_tasks SET name = 'Submit To FM/EC' WHERE name = 'Check In / Submit' AND category = 'Fire Marshal'
  `);
  await db.execute(sql`
    UPDATE tasks SET name = 'Submit To FM/EC' WHERE name = 'Check In / Submit' AND category = 'Fire Marshal'
  `);
  logger.info("Startup complete");
}

// Start listening immediately so Replit's health probe (/api/healthz) passes
// before the DB connection is established. Migrations run right after.
app.listen(port, (err) => {
  if (err) {
    logger.error({ err }, "Error listening on port");
    process.exit(1);
  }
  logger.info({ port }, "Server listening");

  runMigrations().catch((err) => {
    logger.error({ err }, "Migration failed");
    process.exit(1);
  });
});

import { Router } from "express";
import { db, showsTable, tasksTable, eblastsTable } from "@workspace/db";
import { eq } from "drizzle-orm";
const router = Router();

function daysOverdueCount(dueDateStr: string, todayMs: number): number {
  return Math.floor((todayMs - new Date(dueDateStr).getTime()) / 86400000);
}

router.get("/overdue", async (req, res): Promise<void> => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split("T")[0];

  const shows = await db.select().from(showsTable);
  const allTasks = await db.select().from(tasksTable);
  const allEblasts = await db.select().from(eblastsTable);

  const showMap = Object.fromEntries(shows.map((s) => {
    const showTasks = allTasks.filter((t) => t.showId === s.id);
    const fmDeadlineTask = showTasks.find((t) => t.name === "Hard Deadline" && t.category === "Fire Marshal");
    const idSignDeadlineTask = showTasks.find((t) => t.name === "ID Sign Deadline" && t.category === "ID Sign");
    const bucketDueDateTask = showTasks.find((t) => t.name === "Bucket Due Date" && t.category === "Show Bucket");
    return [s.id, {
      name: s.name,
      moveInDate: s.moveInDate,
      fmDeadlineDate: fmDeadlineTask?.dueDate ?? null,
      idSignDeadlineDate: idSignDeadlineTask?.dueDate ?? null,
      bucketDueDate: bucketDueDateTask?.dueDate ?? null,
      advanceWarehouseDate: s.advanceWarehouseDate ?? null,
      onlineOrderDeadline: s.onlineOrderDeadline ?? null,
      discountDeadline: s.discountDeadline ?? null,
    }];
  }));

  const items: {
    id: number;
    type: "task" | "eblast";
    showId: number;
    showName: string;
    name: string;
    dueDate: string;
    category: string | null;
    daysOverdue: number;
    notes: string | null;
    moveInDate: string | null;
    fmDeadlineDate: string | null;
    idSignDeadlineDate: string | null;
    bucketDueDate: string | null;
    advanceWarehouseDate: string | null;
    onlineOrderDeadline: string | null;
    discountDeadline: string | null;
  }[] = [];

  for (const task of allTasks) {
    if (!task.completed && task.dueDate && task.dueDate <= todayStr) {
      items.push({
        id: task.id,
        type: "task",
        showId: task.showId,
        showName: showMap[task.showId]?.name ?? "Unknown Show",
        name: task.name,
        dueDate: task.dueDate,
        category: task.category ?? null,
        daysOverdue: daysOverdueCount(task.dueDate, today.getTime()),
        notes: task.notes ?? null,
        moveInDate: showMap[task.showId]?.moveInDate ?? null,
        fmDeadlineDate: showMap[task.showId]?.fmDeadlineDate ?? null,
        idSignDeadlineDate: showMap[task.showId]?.idSignDeadlineDate ?? null,
        bucketDueDate: showMap[task.showId]?.bucketDueDate ?? null,
        advanceWarehouseDate: showMap[task.showId]?.advanceWarehouseDate ?? null,
        onlineOrderDeadline: showMap[task.showId]?.onlineOrderDeadline ?? null,
        discountDeadline: showMap[task.showId]?.discountDeadline ?? null,
      });
    }
  }

  for (const eblast of allEblasts) {
    if (!eblast.sent && eblast.dueDate && eblast.dueDate <= todayStr) {
      items.push({
        id: eblast.id,
        type: "eblast",
        showId: eblast.showId,
        showName: showMap[eblast.showId]?.name ?? "Unknown Show",
        name: eblast.name,
        dueDate: eblast.dueDate,
        category: null,
        daysOverdue: daysOverdueCount(eblast.dueDate, today.getTime()),
        notes: null,
        moveInDate: showMap[eblast.showId]?.moveInDate ?? null,
        fmDeadlineDate: showMap[eblast.showId]?.fmDeadlineDate ?? null,
        idSignDeadlineDate: showMap[eblast.showId]?.idSignDeadlineDate ?? null,
        bucketDueDate: showMap[eblast.showId]?.bucketDueDate ?? null,
        advanceWarehouseDate: showMap[eblast.showId]?.advanceWarehouseDate ?? null,
        onlineOrderDeadline: showMap[eblast.showId]?.onlineOrderDeadline ?? null,
        discountDeadline: showMap[eblast.showId]?.discountDeadline ?? null,
      });
    }
  }

  items.sort((a, b) => b.daysOverdue - a.daysOverdue);

  res.json(items);
});

router.get("/summary", async (req, res): Promise<void> => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split("T")[0];

  const shows = await db.select().from(showsTable).orderBy(showsTable.moveInDate);
  const allTasks = await db.select().from(tasksTable);
  const allEblasts = await db.select().from(eblastsTable);

  const activeShows = shows.filter((s) => (s.dismantleDate ?? s.moveInDate) >= todayStr);
  const archivedShows = shows.filter((s) => (s.dismantleDate ?? s.moveInDate) < todayStr);

  let totalOverdue = 0;
  for (const task of allTasks) {
    if (!task.completed && task.dueDate && task.dueDate < todayStr) {
      totalOverdue++;
    }
  }
  for (const eblast of allEblasts) {
    if (!eblast.sent && eblast.dueDate && eblast.dueDate < todayStr) {
      totalOverdue++;
    }
  }

  // Next up show (earliest active)
  let nextUpShow = null;
  if (activeShows.length > 0) {
    const show = activeShows[0];
    const tasks = allTasks.filter((t) => t.showId === show.id);
    const eblasts = allEblasts.filter((e) => e.showId === show.id);

    const overdueTasks = tasks.filter(
      (t) => !t.completed && t.dueDate && t.dueDate < todayStr
    );
    const overdueEblasts = eblasts.filter(
      (e) => !e.sent && e.dueDate && e.dueDate < todayStr
    );

    const sentEblasts = eblasts.filter((e) => e.sent).sort((a, b) => {
      if (!a.sentAt || !b.sentAt) return 0;
      return new Date(b.sentAt).getTime() - new Date(a.sentAt).getTime();
    });
    const lastEblast = sentEblasts[0];
    const oldestEblast = sentEblasts[sentEblasts.length - 1];

    const fireMarshalTasks = tasks.filter((t) => t.category === "Fire Marshal");
    let fireMarshalStatus = null;
    let fireMarshalDate = null;
    if (fireMarshalTasks.length > 0) {
      const keyFmTask = fireMarshalTasks.find((t) => t.name === "Submit To FM/EC");
      if (keyFmTask?.completed) {
        fireMarshalStatus = "Submitted";
        fireMarshalDate = keyFmTask.completedAt?.toISOString() ?? null;
      } else {
        fireMarshalStatus = "In Progress";
      }
    }

    const idSignTasks = tasks.filter((t) => t.category === "ID Sign");
    let idSignStatus = null;
    let idSignDate = null;
    if (idSignTasks.length > 0) {
      const keyIdTask = idSignTasks.find((t) => t.name === "Submit Order");
      if (keyIdTask?.completed) {
        idSignStatus = "Ordered";
        idSignDate = keyIdTask.completedAt?.toISOString() ?? null;
      } else {
        idSignStatus = "In Progress";
      }
    }

    nextUpShow = {
      ...show,
      taskCount: tasks.length,
      completedTaskCount: tasks.filter((t) => t.completed).length,
      eblastCount: eblasts.length,
      sentEblastCount: sentEblasts.length,
      overdueCount: overdueTasks.length + overdueEblasts.length,
      lastEblastDate: lastEblast?.sentAt?.toISOString() ?? null,
      exhibitorKitSent: sentEblasts.length > 0,
      exhibitorKitDate: oldestEblast?.sentAt?.toISOString() ?? null,
      fireMarshalStatus,
      fireMarshalDate,
      idSignStatus,
      idSignDate,
    };
  }

  res.json({
    totalShows: shows.length,
    activeShows: activeShows.length,
    archivedShows: archivedShows.length,
    totalOverdue,
    nextUpShow,
  });
});

export default router;

import { Router } from "express";
import { db, showsTable, tasksTable, eblastsTable, linksTable, gcalOrphansTable } from "@workspace/db";
import { eq, and } from "drizzle-orm";
import {
  CreateShowBody,
  UpdateShowBody,
  GetShowParams,
  UpdateShowParams,
  DeleteShowParams,
} from "@workspace/api-zod";

const router = Router();

const DATE_FIELDS = [
  "moveInDate",
  "advanceWarehouseDate",
  "discountDeadline",
  "onlineOrderDeadline",
  "showStart",
  "dismantleDate",
] as const;

function sanitizeDates(body: Record<string, unknown>): Record<string, unknown> {
  const sanitized = { ...body };
  for (const field of DATE_FIELDS) {
    if (sanitized[field] === "" || sanitized[field] === undefined) {
      sanitized[field] = null;
    }
  }
  return sanitized;
}

function toDateStr(d: Date | null | undefined): string | null {
  if (!d) return null;
  return d.toISOString().split("T")[0];
}

function computeShowStats(
  show: typeof showsTable.$inferSelect,
  tasks: (typeof tasksTable.$inferSelect)[],
  eblasts: (typeof eblastsTable.$inferSelect)[]
) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split("T")[0];

  const overdueTasks = tasks.filter(
    (t) => !t.completed && t.dueDate && t.dueDate < todayStr
  );
  const overdueEblasts = eblasts.filter(
    (e) => !e.sent && e.dueDate && e.dueDate < todayStr
  );

  const sentEblasts = eblasts.filter((e) => e.sent).sort((a, b) => {
    if (!a.sentAt || !b.sentAt) return 0;
    return new Date(b.sentAt).getTime() - new Date(a.sentAt).getTime();
  });

  const lastEblast = sentEblasts[0];
  const oldestEblast = sentEblasts[sentEblasts.length - 1];

  // Fire Marshal status
  const fireMarshalTasks = tasks.filter((t) => t.category === "Fire Marshal");
  let fireMarshalStatus: string | null = null;
  let fireMarshalDate: string | null = null;
  if (fireMarshalTasks.length > 0) {
    const keyFmTask = fireMarshalTasks.find((t) => t.name === "Submit To FM/EC");
    if (keyFmTask?.completed) {
      fireMarshalStatus = "Submitted";
      fireMarshalDate = keyFmTask.completedAt?.toISOString() ?? null;
    } else {
      fireMarshalStatus = "In Progress";
    }
  }

  // ID Sign status
  const idSignTasks = tasks.filter((t) => t.category === "ID Sign");
  let idSignStatus: string | null = null;
  let idSignDate: string | null = null;
  if (idSignTasks.length > 0) {
    const keyIdTask = idSignTasks.find((t) => t.name === "Submit Order");
    if (keyIdTask?.completed) {
      idSignStatus = "Ordered";
      idSignDate = keyIdTask.completedAt?.toISOString() ?? null;
    } else {
      idSignStatus = "In Progress";
    }
  }

  // Specific task due dates for the summary line
  const fmDeadlineTask = tasks.find((t) => t.name === "Hard Deadline" && t.category === "Fire Marshal");
  const idSignDeadlineTask = tasks.find((t) => t.name === "ID Sign Deadline" && t.category === "ID Sign");
  const bucketDueDateTask = tasks.find((t) => t.name === "Bucket Due Date" && t.category === "Show Bucket");

  return {
    taskCount: tasks.length,
    completedTaskCount: tasks.filter((t) => t.completed).length,
    eblastCount: eblasts.length,
    sentEblastCount: sentEblasts.length,
    overdueCount: overdueTasks.length + overdueEblasts.length,
    lastEblastDate: lastEblast?.sentAt?.toISOString() ?? null,
    exhibitorKitSent: sentEblasts.length > 0,
    exhibitorKitDate: oldestEblast?.sentAt?.toISOString() ?? null,
    fireMarshalStatus,
    fireMarshalDate,
    idSignStatus,
    idSignDate,
    fmDeadlineDate: fmDeadlineTask?.dueDate ?? null,
    idSignDeadlineDate: idSignDeadlineTask?.dueDate ?? null,
    bucketDueDate: bucketDueDateTask?.dueDate ?? null,
  };
}

router.get("/", async (req, res): Promise<void> => {
  const shows = await db.select().from(showsTable).orderBy(showsTable.moveInDate);
  const allTasks = await db.select().from(tasksTable);
  const allEblasts = await db.select().from(eblastsTable);

  const result = shows.map((show) => {
    const tasks = allTasks.filter((t) => t.showId === show.id);
    const eblasts = allEblasts.filter((e) => e.showId === show.id);
    return { ...show, ...computeShowStats(show, tasks, eblasts) };
  });

  res.json(result);
});

router.post("/", async (req, res): Promise<void> => {
  const parsed = CreateShowBody.safeParse(sanitizeDates(req.body));
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.message });
    return;
  }

  const values = {
    name: parsed.data.name,
    moveInDate: toDateStr(parsed.data.moveInDate)!,
    venue: parsed.data.venue ?? null,
    advanceWarehouseDate: toDateStr(parsed.data.advanceWarehouseDate),
    discountDeadline: toDateStr(parsed.data.discountDeadline),
    onlineOrderDeadline: toDateStr(parsed.data.onlineOrderDeadline),
    showStart: toDateStr(parsed.data.showStart),
    dismantleDate: toDateStr(parsed.data.dismantleDate),
    tags: parsed.data.tags ?? [],
  };

  const [show] = await db.insert(showsTable).values(values).returning();
  res.status(201).json({ ...show, taskCount: 0, completedTaskCount: 0, eblastCount: 0, sentEblastCount: 0, overdueCount: 0, lastEblastName: null, lastEblastDate: null, exhibitorKitSent: false, exhibitorKitDate: null, fireMarshalStatus: null, fireMarshalDate: null, idSignStatus: null });
});

router.get("/:showId", async (req, res): Promise<void> => {
  const params = GetShowParams.safeParse({ showId: Number(req.params.showId) });
  if (!params.success) {
    res.status(400).json({ error: "Invalid show ID" });
    return;
  }

  const [show] = await db.select().from(showsTable).where(eq(showsTable.id, params.data.showId));
  if (!show) {
    res.status(404).json({ error: "Show not found" });
    return;
  }

  const tasks = await db.select().from(tasksTable).where(eq(tasksTable.showId, show.id));
  const eblasts = await db.select().from(eblastsTable).where(eq(eblastsTable.showId, show.id));
  const links = await db.select().from(linksTable).where(eq(linksTable.showId, show.id));

  res.json({ ...show, ...computeShowStats(show, tasks, eblasts), tasks, eblasts, links });
});

router.put("/:showId", async (req, res): Promise<void> => {
  const params = UpdateShowParams.safeParse({ showId: Number(req.params.showId) });
  if (!params.success) {
    res.status(400).json({ error: "Invalid show ID" });
    return;
  }

  const parsed = UpdateShowBody.safeParse(sanitizeDates(req.body));
  if (!parsed.success) {
    res.status(400).json({ error: parsed.error.message });
    return;
  }

  const values = {
    name: parsed.data.name,
    moveInDate: toDateStr(parsed.data.moveInDate)!,
    venue: parsed.data.venue ?? null,
    advanceWarehouseDate: toDateStr(parsed.data.advanceWarehouseDate),
    discountDeadline: toDateStr(parsed.data.discountDeadline),
    onlineOrderDeadline: toDateStr(parsed.data.onlineOrderDeadline),
    showStart: toDateStr(parsed.data.showStart),
    dismantleDate: toDateStr(parsed.data.dismantleDate),
    tags: parsed.data.tags ?? [],
  };

  const [show] = await db
    .update(showsTable)
    .set(values)
    .where(eq(showsTable.id, params.data.showId))
    .returning();

  if (!show) {
    res.status(404).json({ error: "Show not found" });
    return;
  }

  const tasks = await db.select().from(tasksTable).where(eq(tasksTable.showId, show.id));
  const eblasts = await db.select().from(eblastsTable).where(eq(eblastsTable.showId, show.id));

  res.json({ ...show, ...computeShowStats(show, tasks, eblasts) });
});

router.delete("/:showId", async (req, res): Promise<void> => {
  const params = DeleteShowParams.safeParse({ showId: Number(req.params.showId) });
  if (!params.success) {
    res.status(400).json({ error: "Invalid show ID" });
    return;
  }

  const [childTasks, childEblasts] = await Promise.all([
    db.select({ gcalEventId: tasksTable.gcalEventId }).from(tasksTable).where(eq(tasksTable.showId, params.data.showId)),
    db.select({ gcalEventId: eblastsTable.gcalEventId }).from(eblastsTable).where(eq(eblastsTable.showId, params.data.showId)),
  ]);

  const taskOrphanIds = childTasks.map((t) => t.gcalEventId).filter((id): id is string => !!id);
  const eblastOrphanIds = childEblasts.map((e) => e.gcalEventId).filter((id): id is string => !!id);
  const allOrphans = [
    ...taskOrphanIds.map((gcalEventId) => ({ gcalEventId, calendarType: "task" as const })),
    ...eblastOrphanIds.map((gcalEventId) => ({ gcalEventId, calendarType: "eblast" as const })),
  ];

  if (allOrphans.length > 0) {
    await db.insert(gcalOrphansTable).values(allOrphans);
  }

  await db.delete(showsTable).where(eq(showsTable.id, params.data.showId));
  res.status(204).send();
});

export default router;
